import React, { useEffect } from "react";
import Menu from "./Menu";

const TopBar = () => {
  useEffect(() => {
    const container = document.getElementById("tradingview-widget");

    // 1. Pehle se agar koi script ya widget hai toh use hata do
    if (container) {
      container.innerHTML = ""; 
    }

    // 2. Nayi script create karo
    const script = document.createElement("script");
    script.src = "https://s3.tradingview.com/external-embedding/embed-widget-tickers.js";
    script.async = true;
    script.type = "text/javascript"; // Type define karna zaroori hai

    script.innerHTML = JSON.stringify({
      "symbols": [
        { "proName": "FOREXCOM:NSXUSD", "title": "NIFTY 50" },
        { "proName": "INDEX:SENSEX", "title": "SENSEX" }
      ],
      "colorTheme": "light",
      "isTransparent": true,
      "showSymbolLogo": false,
      "locale": "in"
    });

    // 3. Script ko container mein daalo
    if (container) {
      container.appendChild(script);
    }

    // 4. Cleanup function (Jab component unmount ho ya refresh ho)
    return () => {
      if (container) {
        container.innerHTML = "";
      }
    };
  }, []); // Empty array matlab sirf ek baar chalega

  return (
    <div className="topbar-container" style={{ display: "flex", justifyContent: "space-between", alignItems: "center", height: "60px", padding: "0 20px" }}>
      <div id="tradingview-widget" style={{ width: "450px" }}></div>
      <Menu />
    </div>
  );
};

export default TopBar;
